from datetime import date
import calendar

# subclassing the built-in ValueError to create MeetupDayException
class MeetupDayException(ValueError):
    """Exception raised when the Meetup weekday and count do not result in a valid date.

    message: explanation of the error.

    """
    def __init__(self, message):
        super().__init__(message)
        self.message = message


def meetup(year, month, week, day_of_week):
    # Normalize weekday name (allow e.g. 'monday' or 'Monday')
    day_name = day_of_week.strip().capitalize()

    weekdays = {
        'Monday': 0,
        'Tuesday': 1,
        'Wednesday': 2,
        'Thursday': 3,
        'Friday': 4,
        'Saturday': 5,
        'Sunday': 6,
    }

    if day_name not in weekdays:
        raise MeetupDayException(f"Invalid weekday name: {day_of_week!r}")

    target_wd = weekdays[day_name]

    # get number of days in month
    _, days_in_month = calendar.monthrange(year, month)

    # collect all dates in the month matching the target weekday
    matching = []
    for day in range(1, days_in_month + 1):
        if date(year, month, day).weekday() == target_wd:
            matching.append(date(year, month, day))

    week = week.strip().lower()

    if week == 'teenth':
        for d in matching:
            if 13 <= d.day <= 19:
                return d
        raise MeetupDayException(f"No teenth {day_of_week} in {month}/{year}")

    if week == 'first':
        if len(matching) >= 1:
            return matching[0]
        raise MeetupDayException(f"No first {day_of_week} in {month}/{year}")

    if week == 'second':
        if len(matching) >= 2:
            return matching[1]
        raise MeetupDayException(f"No second {day_of_week} in {month}/{year}")

    if week == 'third':
        if len(matching) >= 3:
            return matching[2]
        raise MeetupDayException(f"No third {day_of_week} in {month}/{year}")

    if week == 'fourth':
        if len(matching) >= 4:
            return matching[3]
        raise MeetupDayException(f"No fourth {day_of_week} in {month}/{year}")

    if week == 'fifth':
        if len(matching) >= 5:
            return matching[4]
        raise MeetupDayException(f"No fifth {day_of_week} in {month}/{year}")

    if week == 'last':
        if matching:
            return matching[-1]
        raise MeetupDayException(f"No last {day_of_week} in {month}/{year}")

    raise MeetupDayException(f"Invalid week descriptor: {week!r}")
